package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BigFraction_floatValue_TriageGen4Test {

    private static final float EPSILON = 1e-7f;

    @Test
    public void testFloatValue_SimpleFraction() {
        // 1/2 = 0.5f
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_IntegerNumerator() {
        // 5/1 = 5.0f
        BigFraction fraction = new BigFraction(5);
        assertEquals(5.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeNumerator() {
        // -1/4 = -0.25f
        BigFraction fraction = new BigFraction(new BigInteger("-1"), new BigInteger("4"));
        assertEquals(-0.25f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeDenominator() {
        // 1/-4 = -0.25f
        BigFraction fraction = new BigFraction(new BigInteger("1"), new BigInteger("-4"));
        assertEquals(-0.25f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_BothNegative() {
        // -1/-2 = 0.5f
        BigFraction fraction = new BigFraction(new BigInteger("-1"), new BigInteger("-2"));
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_ZeroNumerator() {
        // 0/5 = 0.0f
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_LargeValues() {
        // Test precision and potential overflow handling before conversion to float
        // BigInteger values that are larger than float.MAX_VALUE
        BigInteger largeNum = new BigInteger("1000000000000000000000000000000000000000"); 
        BigInteger den = BigInteger.ONE;
        BigFraction fraction = new BigFraction(largeNum, den);

        // floatValue() should return Infinity if the result is too large for float
        assertEquals(Float.POSITIVE_INFINITY, fraction.floatValue(), 0.0f);
    }

    @Test
    public void testFloatValue_VerySmallFraction() {
        // 1 / 10^40 (very small)
        BigInteger num = BigInteger.ONE;
        BigInteger den = BigInteger.TEN.pow(40);
        BigFraction fraction = new BigFraction(num, den);

        // Should result in 0.0f due to float precision limits
        assertEquals(0.0f, fraction.floatValue(), 0.0f);
    }

    @Test
    public void testFloatValue_PrecisionLoss() {
        // Test a value that cannot be represented exactly in float
        // 1/3 is a classic case
        BigFraction fraction = new BigFraction(1, 3);
        float expected = 1.0f / 3.0f;
        assertEquals(expected, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_DivideByZeroBehavior() {
        // Note: BigFraction constructor usually prevents denominator 0, 
        // but if we assume the math logic of the method:
        // This test checks if the numerator/denominator conversion handles extreme scales.
        // Since we cannot easily instantiate a BigFraction with 0 denominator via constructor,
        // we test the limits of the float conversion.
        BigFraction fraction = new BigFraction(1, 1);
        // If denominator was somehow 0, float division 1.0f / 0.0f = Infinity
        // This is more of a logic check on the division operation itself.
    }
}
